        "permission": "openrouter_list-daily-model-rankings",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "openrouter.list-model-endpoints",
        "permission": "openrouter_list-model-endpoints",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "openrouter.list-models",
