        "readOnly": true
      },
      {
        "name": "openrouter.list-providers",
        "permission": "openrouter_list-providers",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "openrouter.list-task-classifications",
        "permission": "openrouter_list-task-classifications",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "openrouter.ping",
        "permission": "openrouter_ping",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "openrouter.search-docs",
        "permission": "openrouter_search-docs",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "openrouter.get-batch",
        "permission": "openrouter_get-batch",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "openrouter.get-credits",
        "permission": "openrouter_get-credits",
        "effect": "allow",
